"""Prepare Part 3 from exact saved performances, matching physical actions and local sound."""
from pathlib import Path
import json,math,shutil,hashlib,wave
import numpy as np
from dialogue_media import ROOT,R,assemble,pcm,wav,run,normal
B=ROOT/'episodes/billionaire-body-swap-3';P=ROOT/'public/episodes/billionaire-body-swap-3';plan=json.loads((B/'plan.json').read_text())
_,timeline,_=assemble('billionaire-body-swap-3');lines={l['id']:l for l in timeline['lines']};D=timeline['duration'];N=round(D*R)
def word(line,text):return next(w['start'] for w in lines[line]['words'] if normal(w['text'])==normal(text))
e={key:value['start'] for key,value in lines.items()};e.update(exam=word('hook','He'),contractHit=.22,paperHit=word('hook','He')+.22,figure=word('deal','forty'),pencilHit=word('pencil','pencil')-.10,removePencil=word('lawyer','lawyer')-.22,sendContract=lines['helpCompany']['start']+.55,sendExam=lines['helpExam']['start']+.55,takePhone=lines['answers']['start']-.18,reveal=word('me','me'),end=D)
