starts=[('office-hook',0,'swap-office'),('exam-hook',e['exam'],'swap-classroom'),('working',e['working'],'swap-classroom'),('accountant',e['accountant'],'swap-classroom'),('pencil',e['pencil'],'swap-classroom'),('deal',e['deal'],'swap-office'),('contract',e['figure']-.08,'swap-office'),('pencil2',e['pencil2'],'swap-office'),('lawyer',e['lawyer'],'swap-office'),('helpCompany',e['helpCompany'],'swap-office'),('helpExam',e['helpExam'],'swap-classroom'),('answers',e['answers'],'swap-classroom'),('me',e['me'],'swap-classroom'),('reveal',e['reveal'],'swap-classroom'),('reaction',e['reaction'],'swap-classroom')]
descriptions={'office-hook':'Contract already dropping toward the suited red-scarf viewer.','exam-hook':'Match cut to the maths paper landing in front of the young body.','working':'Teacher points at the unanswered working-out space.','accountant':'Young body confidently asks to call an accountant.','pencil':'One pencil arrives on the desk instead.','deal':'Assistant introduces the contract waiting for a signature.','contract':'Close-up shows the fictional forty-million-pound amount.','pencil2':'Viewer hopes the school solution will work here too.','lawyer':'Assistant removes the pencil on the legal retort.','helpCompany':'Adult viewer calls the young body for help.','helpExam':'Young body asks for help with the exam and shares its photo.','answers':'Teacher has taken the phone and questions the young body.','me':'Caught young body hesitates before his literal answer.','reveal':'Phone reveals the adult red-scarf caller giving a guilty wave.','reaction':'Teacher holds an unimpressed reaction after the completed wave.'}
shots=[{'id':id,'start':start,'duration':(starts[i+1][1] if i+1<len(starts) else D)-start,'set':set,'action':'handoff' if id in ['pencil','answers'] else 'reveal','anchor':lines[id if id in lines else 'hook' if 'hook' in id else 'deal' if id=='contract' else 'me']['text'],'description':descriptions[id]} for i,(id,start,set) in enumerate(starts)]
for s in shots:assert s['duration']>0,s
assets=[]
for id,a in json.loads((B/'assets/poses.json').read_text()).items():assets.append({'id':id,'url':a['file'],'width':a['width'],'height':a['height'],'worldHeight':a['worldHeight'],'pivotX':a['pivotX'],'footY':a['footY']})
for id,a in json.loads((B/'assets/animations.json').read_text()).items():
 m=a['metadata'];c=m['crop'];assets.append({'id':id+'-gif','url':a['file'],'width':c['width'],'height':c['height'],'worldHeight':a['worldHeight'],'pivotX':m['cellWidth']/2-c['x'],'footY':c['height'],'animation':m})
edit={'id':plan['id'],'title':plan['title'],'width':1080,'height':1920,'fps':30,'duration':D,'events':e,'lines':list(lines.values()),'shots':shots,'assets':assets,'model':'episodes/billionaire-body-swap-3/swap-stage-3.glb','ui':plan['ui']}
(B/'edit.json').write_text(json.dumps(edit,indent=2)+'\n')
ledger=json.loads((ROOT/'episodes/billionaire-body-swap-2/assets/sfx-ledger.json').read_text());sounds={r['id']:pcm(ROOT/r['localFile']) for r in ledger};fx=np.zeros(N);events=[]
def sound(id,key,t,d=.20,gain=.055):
 t=max(0,t);start=round(t*R);n=min(round(d*R),len(sounds[key]),N-start);a=sounds[key][:n].copy();a*=gain/max(.001,float(np.max(np.abs(a))));edge=min(round(.005*R),n//2);a[:edge]*=np.linspace(0,1,edge);a[-edge:]*=np.linspace(1,0,edge);fx[start:start+n]+=a;events.append({'id':id,'sound':key,'start':t,'duration':n/R,'peakGain':gain})
sound('contract-falling','swoosh',0,.22,.045);sound('contract-impact','folder',e['contractHit'],.25,.11);sound('exam-lands','folder',e['paperHit'],.22,.095)
for s in shots[1:]:sound(s['id']+'-cut','swoosh',s['start'],.15,.026)
sound('pencil-offered','tap',e['pencilHit'],.13,.065);sound('pencil-slides-away','folder',e['removePencil'],.28,.060)
sound('call-connects','tap',e['helpCompany']+.03,.12,.045);sound('contract-photo-sent','snap',e['sendContract'],.10,.045);sound('exam-photo-sent','snap',e['sendExam'],.10,.045)
sound('phone-confiscated','folder',e['takePhone'],.26,.08);sound('phone-reveal','swoosh',e['reveal'],.20,.045);sound('small-guilty-wave','swoosh',e['reveal']+.35,.28,.020)
wav(P/'effects-mono.wav',fx);run(['ffmpeg','-v','error','-y','-i',str(P/'effects-mono.wav'),'-af','pan=stereo|c0=c0|c1=c0',str(P/'effects.wav')]);(B/'audio-events.json').write_text(json.dumps(events,indent=2)+'\n');(B/'assets/sfx-ledger.json').write_text(json.dumps(ledger,indent=2)+'\n')
