ep=json.loads((ROOT/'episodes/billionaire-body-swap-2/episode.json').read_text());ep.update(id=plan['id'],title=plan['title'],renderer='remotion',world='swap3',number=25,premise='You and the billionaire secretly help each other through your maths exam and his company contract.',duration=D,fps=30,cast=['miko','billionaire','teacher','assistant'],audio={'narration':'episodes/billionaire-body-swap-3/narration.wav','music':'episodes/billionaire-body-swap-3/music.wav','effects':'episodes/billionaire-body-swap-3/effects.wav','narrationOffset':0,'narrationTrimStart':0,'narrationTail':D-lines['me']['words'][-1]['end'],'pauses':[]},scenes=[{**s,'label':s['id'],'timeOfDay':'evening'} for s in shots]);(B/'episode.json').write_text(json.dumps(ep,indent=2)+'\n')
print(json.dumps({'duration':D,'frames':round(D*30),'words':sum(len(l['words']) for l in lines.values()),'shots':len(shots),'events':e}))
